import{InteractionTracker}from"../../js-modules/interaction-tracker.js";import{AdaptivePreferenceEngine}from"../../js-modules/adaptive-preference-engine.js";import{AdaptiveRecommender}from"../../js-modules/adaptive-recommend.js";const tracker=new InteractionTracker,destinations="undefined"!=typeof window&&window.TRAVEL_DESTINATIONS||[],engine=new AdaptivePreferenceEngine({destinations:destinations}),recommender=new AdaptiveRecommender(destinations),confidenceFill=document.getElementById("confidence-fill"),confidenceLabel=document.getElementById("confidence-label"),topTagsList=document.getElementById("top-tags-list"),budgetAffinityEl=document.getElementById("budget-affinity"),signalCountEl=document.getElementById("signal-count"),recommendationList=document.getElementById("recommendation-list"),resetBtn=document.getElementById("reset-btn");function render(){const e=tracker.getEvents(),n=engine.buildProfile(e),t=Math.round(100*n.confidence);confidenceFill.style.width=`${t}%`,confidenceLabel.textContent=AdaptivePreferenceEngine.isColdStart(n)?`Just getting started (${t}%) — browse, bookmark, or rate a few destinations to sharpen this.`:`${t}% confident — recommendations below are personalized to you.`;const i=AdaptivePreferenceEngine.getTopTags(n,5);topTagsList.innerHTML=i.length?i.map(e=>`<li class="tag-pill">${e}</li>`).join(""):'<li class="tag-pill tag-pill--empty">No strong interests learned yet</li>';const o=AdaptivePreferenceEngine.getPreferredBudget(n);budgetAffinityEl.textContent=o?`You tend to plan ${o}-tier trips.`:"Not enough data yet.",signalCountEl.textContent=`${n.eventCount} recorded interaction${1===n.eventCount?"":"s"}.`;const r=recommender.recommend({profile:n,limit:6});recommendationList.innerHTML=r.map(({dest:e,explanation:n})=>`\n      <div class="rec-item">\n        <h3>${e.name}</h3>\n        <p class="rec-item__tagline">${e.tagline||""}</p>\n        <p class="rec-item__explanation">💡 ${n}</p>\n      </div>`).join("")||"<p>Add a few destinations to the travel dataset to see recommendations here.</p>"}resetBtn.addEventListener("click",()=>{confirm("Reset your learned preference profile? This cannot be undone.")&&(tracker.clearEvents(),render())}),render();